def val(label,expr,key,kp,direct,method,components=None,units=None,show=False,part=None):
 p=v(label,expr,key,kp,method);p.update(assessed_8227_demand_ids=direct,component_demand_ids=components or [],response_format='proof/show-that' if show else 'symbolic')
 if units:p.update(units=units,printed_key_units=units)
 if show:p['check_mode']='show/prove'
 if part:p['source_part']=part
 return p
def add(kind,n,page,note,parts,powers,rep='graph',tariffs=None,continuation=None):
 direct=sorted({d for p in parts for d in p.get('assessed_8227_demand_ids',[])})
 comp=sorted({d for p in parts for d in p.get('component_demand_ids',[])}-set(direct))
 r=h.add(kind,n,page,note,parts,direct,comp,powers=powers)
 r.update(representation=rep,exam_style=True,exam_style_basis='Source section7.3 Exam-Style Questions starts369 and includes this final practice/revision. Textbook-derived practice,not an official examination attribution.',mapping_rationale='Preserve each requested area,rotation axis,tangent or motion result and its actual region. Shared printed part tariffs are counted once even when a part requests two outputs. Source boundary ambiguities and implicit conventions remain explicit rather than becoming silent constraints.')
 for p in parts:p['given_representation']=rep
 if continuation:
  r['continuation_pdf_pages']=continuation;corrections[-1]['continuation_pdf_pages']=continuation
 if tariffs:
  r.update(source_part_tariffs=tariffs,source_total_marks=sum(tariffs.values()),source_marks_kind='Textbook printed tariffs;no official criterion schedule supplied.')
  assert all(p['source_part'] in tariffs for p in parts)
 return r
